mod blr_demo;

use blr_demo::{Object, Scene};

fn main() {
    let mut scene = Scene::new();
    scene
        .add(
            Object::cube("foundation", 3.4)
                .at([0.0, 0.0, 0.35])
                .scaled([1.0, 1.0, 0.2])
                .colored([0.22, 0.28, 0.38, 1.0]),
        )
        .expect("valid foundation");

    for floor in 0..7 {
        let height = 0.8 + floor as f64 * 0.72;
        let width = 2.7 - floor as f64 * 0.24;
        scene
            .add(
                Object::cube(format!("tower floor {floor}"), 1.0)
                    .at([0.0, 0.0, height])
                    .scaled([width, width, 0.34])
                    .colored([
                        0.32 + floor as f64 * 0.045,
                        0.48 + floor as f64 * 0.025,
                        0.78 - floor as f64 * 0.055,
                        1.0,
                    ]),
            )
            .expect("valid tower floor");
    }

    scene
        .add(
            Object::cone("roof", 1.05, 1.5)
                .at([0.0, 0.0, 6.7])
                .segments(8)
                .colored([0.92, 0.37, 0.12, 1.0]),
        )
        .expect("valid roof");
    scene.emit().expect("emit scene");
}

mod blr_demo;

use blr_demo::{Object, Scene};
use std::f64::consts::TAU;

fn main() {
    let mut scene = Scene::new();
    scene
        .add(
            Object::sphere("central star", 0.92)
                .segments(24)
                .rings(12)
                .colored([1.0, 0.48, 0.08, 1.0]),
        )
        .expect("valid star");
    scene
        .add(
            Object::torus("tilted orbit", 2.15, 0.07)
                .rotated([0.28, 0.16, 0.0])
                .major_segments(48)
                .minor_segments(10)
                .colored([0.16, 0.68, 0.88, 1.0]),
        )
        .expect("valid orbit");

    for moon in 0..8 {
        let angle = TAU * moon as f64 / 8.0;
        scene
            .add(
                Object::sphere(format!("moon {moon}"), 0.2 + (moon % 3) as f64 * 0.045)
                    .at([2.15 * angle.cos(), 2.15 * angle.sin(), 0.0])
                    .segments(12)
                    .rings(8)
                    .colored([0.38, 0.78 - moon as f64 * 0.035, 0.42, 1.0]),
            )
            .expect("valid moon");
    }
    scene.emit().expect("emit scene");
}

