use blr_demo::{Object, Scene};

fn main() {
    let mut scene = Scene::new();
    scene
        .add(
            Object::plane("ground", 9.0)
                .at([0.0, 0.0, -0.18])
                .colored([0.16, 0.22, 0.27, 1.0]),
        )
        .expect("valid ground");
    scene
        .add(
            Object::cube("beacon base", 1.1)
                .at([-2.4, 0.0, 0.45])
                .scaled([1.0, 1.0, 0.8])
                .colored([0.8, 0.22, 0.16, 1.0]),
        )
        .expect("valid cube");
    scene
        .add(
            Object::sphere("beacon globe", 0.72)
                .at([-2.4, 0.0, 1.55])
                .segments(20)
                .rings(12)
                .colored([0.98, 0.78, 0.18, 1.0]),
        )
        .expect("valid sphere");
    scene
        .add(
            Object::cylinder("column", 0.58, 2.0)
                .at([0.0, 0.0, 0.82])
                .segments(20)
                .colored([0.18, 0.56, 0.78, 1.0]),
        )
        .expect("valid cylinder");
    scene
        .add(
            Object::cone("spire", 0.86, 1.7)
                .at([0.0, 0.0, 2.68])
                .segments(16)
                .colored([0.9, 0.36, 0.16, 1.0]),
        )
        .expect("valid cone");
    scene
        .add(
            Object::cone("frustum", 0.72, 1.5)
                .bottom_radius(0.3)
                .at([2.35, 0.0, 0.8])
                .segments(16)
                .colored([0.68, 0.32, 0.78, 1.0]),
        )
        .expect("valid cone frustum");
    scene
        .add(
            Object::torus("ring sculpture", 0.82, 0.14)
                .at([2.35, 0.0, 1.95])
                .rotated([0.65, 0.2, 0.0])
                .colored([0.16, 0.82, 0.58, 1.0]),
        )
        .expect("valid torus");
    scene.emit().expect("emit scene");
}

mod blr_demo;

use blr_demo::{Object, Scene};

fn main() {
    let mut scene = Scene::new();
    let cells = 8;
    for x in 0..cells {
        for y in 0..cells {
            let fx = x as f64 / (cells - 1) as f64;
            let fy = y as f64 / (cells - 1) as f64;
            let wave = (fx * 9.0).sin() * (fy * 8.0).cos();
            let height = 0.34 + (wave + 1.0) * 0.44;
            let color = [
                0.13 + fx * 0.18,
                0.3 + fy * 0.42,
                0.19 + (wave + 1.0) * 0.12,
                1.0,
            ];
            scene
                .add(
                    Object::cube(format!("tile {x}-{y}"), 1.0)
                        .at([x as f64 - 3.5, y as f64 - 3.5, height * 0.5])
                        .scaled([0.47, 0.47, height * 0.5])
                        .colored(color),
                )
                .expect("heightfield fits bridge limits");
        }
    }
    scene.emit().expect("emit scene");
}
